def apply(copy, ui, deep):
 for lang, x in TEXT.items():
  t=copy[lang]
  for key in ('claimA','claimB','claimBody','kicker','kickerMeta','leftBody','leftLink','offerCta','servicesTitle','servicesIntro','ctaBand','ctaBandBody','claim'):
   t[key]=x[key]
  t['legal']={'nl':'© 2026 marleo.tech · Alle rechten voorbehouden','en':'© 2026 marleo.tech · All rights reserved','fr':'© 2026 marleo.tech · Tous droits réservés'}[lang]
  ui[lang]['footerMade']='AI · SOFTWARE · CLOUD · SECURITY · WEB'
  t['metrics']=[{'value':a,'label':b} for a,b in x['why']]
  t['labels']['ai-infrastructuur']=x['aiLabel']; t['navDesc']['ai-infrastructuur']=x['aiDesc']
  groups=t['navGroups']; ai=next(g for g in groups if 'ai-infrastructuur' in g.get('keys',[])); groups.remove(ai); groups.insert(0,ai)
  # Existing URL is retained for search engines and inbound links.
  p=t['pages']['ai-infrastructuur'];p.update(crumb=x['aiLabel'],title=x['aiTitle'],lead=x['aiLead'],blocksTitle=x['blocksTitle'],stepsTitle=x['stepsTitle'])
  p['blocks']=[dict(abbr=a,title=b,body=c) for a,b,c in x['blocks']]
  p['steps']=[dict(n=f'{i+1:02d}',title=a,body=b) for i,(a,b) in enumerate(x['steps'])]
  p['faq']=[dict(q=a,a=b) for a,b in x['faq']]
  # Old infrastructure-only supporting copy would contradict the new process focus.
  if 'ai-infrastructuur' in deep:deep['ai-infrastructuur'].pop(lang,None)
  d=t['pages']['diensten'];d.update(title=x['servicesTitle'],lead=x['servicesIntro'],serviceGridTitle=x['servicesTitle'],stepsTitle=x['stepsTitle'],steps=p['steps'])
  pr=t['pages']['prijzen'];pr.update(title=x['pricingTitle'],lead=x['pricingLead'])
  pr['faq'][1]['a']=x['pricingIntro']
  pr['plans'][2]['items'][2]={'nl':'AI-planning; maatwerk apart begroot','en':'AI planning; custom builds quoted separately','fr':'Planification IA ; sur mesure chiffré séparément'}[lang]
  projects=t['pages']['projecten']
  projects['credLabel']={'nl':'Persoonlijke werkervaring van Giannis','en':'Giannis’s professional experience','fr':'Expérience professionnelle de Giannis'}[lang]
  for item in projects.get('faq',[]):
   if 'enterprise' in item['q'].lower():item['a']={'nl':'Giannis heeft ervaring met IT-support bij Procter & Gamble. Voor een groter project leggen we apart de benodigde expertise, capaciteit, verantwoordelijkheden en ondersteuning vast.','en':'Giannis has IT support experience at Procter & Gamble. For larger projects, required expertise, capacity, responsibilities and support are scoped separately.','fr':'Giannis a une expérience en support IT chez Procter & Gamble. Pour un projet important, expertise, capacité, responsabilités et assistance sont définies séparément.'}[lang]
  ui[lang]['metaHome']=x['claimBody']+' '+x['servicesIntro']

